export const buildDemographicFilterValue = (
  selected: string[],
  allOptions: string[],
): string => {
  const isAll =
    allOptions.length > 0 && allOptions.every((opt) => selected.includes(opt));
  return isAll ? 'All' : selected.join(',');
};
